class AuthenticatedAction @Inject() (verifier: TokenVerifier)
    extends ActionBuilder[AuthenticatedRequest, AnyContent] {
  def invokeBlock[A](request: Request[A], block: AuthenticatedRequest[A] => Future[Result]) =
    request.headers.get("Authorization") match {
      case Some(h) => verifier.verify(h) match {            // delegated mechanism
        case Some(p) => block(new AuthenticatedRequest(p, request))
        case None    => Future.successful(Unauthorized)
      }
      case None => Future.successful(Unauthorized)          // single challenge site
    }
}
